import{_ as r,o as a,c as t,ag as o}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Release","description":"","frontmatter":{},"headers":[],"relativePath":"release/index.md","filePath":"release/index.md"}'),i={name:"release/index.md"};function n(s,e,d,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h1><h2 id="current-provider-release" tabindex="-1">Current Provider release <a class="header-anchor" href="#current-provider-release" aria-label="Permalink to &quot;Current Provider release&quot;">​</a></h2><p>Provider <strong>v3.0.0</strong> is the current Registry-published Terraform/OpenTofu Provider. It registers 31 typed resources across eight versionless families; each resource keeps an exact FormRef and provider mapping in its release identity projection. Provider release, Form Definition publication, package publication, and Host deployment are separate owner actions.</p><p>The signed release-tag commit must be an ancestor of the reviewed protected-main/readback commit used for the release.</p><p>The release identity and Registry readback are recorded in the <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/provider-release-identities.json" target="_blank" rel="noreferrer">Provider release identity ledger</a>. The <a href="./../docs/">Provider reference</a> contains the install pin and generated resource contracts.</p><h2 id="compatibility-and-migration" tabindex="-1">Compatibility and migration <a class="header-anchor" href="#compatibility-and-migration" aria-label="Permalink to &quot;Compatibility and migration&quot;">​</a></h2><h3 id="retained-v1beta1-history-provider-2-1-1" tabindex="-1">Retained v1beta1 history (Provider 2.1.1) <a class="header-anchor" href="#retained-v1beta1-history-provider-2-1-1" aria-label="Permalink to &quot;Retained v1beta1 history (Provider 2.1.1)&quot;">​</a></h3><p>Provider 2.1.1 remains the compatibility predecessor. Its identity ledger retains 15 exact v1beta1 Form identities; 14 remain readable by Provider 3 state/import dispatch. ObjectBucket has no Provider 3 resource or codec, so ObjectBucket state needs explicit pre-upgrade handling. Existing Provider 2 state needs an explicit cutover; follow <a href="./migrations/v2-to-v3.html">v2 to v3 migration</a> before changing the required provider version. Provider 3 does not rewrite Provider 1 state; the <a href="./migrations/v1-to-v2.html">v1 to v2 migration</a> is the earlier boundary.</p><p>The current mapping groups are rooted at <code>edge.forms.takoform.com</code> and use <code>packages.forms.takoform.com/v1alpha5</code>. Retained Provider 2.1.1 history uses Host API <code>forms.takoform.com/v1beta1</code>, family <code>edge.forms.takoform.com/v1beta1</code>, and package envelope <code>packages.forms.takoform.com/v1alpha4</code>.</p><p>The <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/website/docs/versions.md" target="_blank" rel="noreferrer">versions page</a> lists the current API/Core checkpoint, Provider releases, package publication, and retained history in one place.</p><h2 id="core-and-specification-history" tabindex="-1">Core and Specification history <a class="header-anchor" href="#core-and-specification-history" aria-label="Permalink to &quot;Core and Specification history&quot;">​</a></h2><p>The current Core/API checkpoint is <a href="https://github.com/tako0614/takoform/tree/v1.0.1/spec" target="_blank" rel="noreferrer">Core v1.0.1</a> on <code>forms.takoform.com/v1</code>. Specification 1.1 is retained as an immutable historical source receipt.</p><p>Release tooling and ledgers are maintained in the <a href="https://github.com/tako0614/terraform-provider-takoform/tree/main/release" target="_blank" rel="noreferrer">Provider repository</a>. They provide Provider provenance and migration evidence.</p>',13)])])}const v=r(i,[["render",n]]);export{m as __pageData,v as default};
